// The site's still frames of the works field (effect/stills, public/brand/light/field/works-*.webp), embedded: what the
// product hero shows from 1024 wide while the field's WebGL starts, one per width range, so the first paint already has
// the light. Pass them to the dispersion field as `stills` with composition "works". Spyglass's art. Only the desktop
// ranges ship (the stills are hidden below 1024).
export interface FieldStill { src: string, media: string }

const media = (from: number, to?: number) => (to ? `(min-width: ${from}px) and (max-width: ${to - 0.02}px)` : `(min-width: ${from}px)`)

export const WORKS_STILLS: FieldStill[] = [
	{ src: 'data:image/webp;base64,', media: media(1024, 1200) },
	{ src: 'data:image/webp;base64,', media: media(1200, 1360) },
	{ src: 'data:image/webp;base64,', media: media(1360, 1476) },
	{ src: 'data:image/webp;base64,', media: media(1476, 1620) },
	{ src: 'data:image/webp;base64,', media: media(1620, 1824) },
	{ src: 'data:image/webp;base64,', media: media(1824, 2240) },
	{ src: 'data:image/webp;base64,', media: media(2240) },
]
